sys_script_fix.script:
var users = [];
var i;
var trigID = '5749e57a47597150020ba9f8536d436b';

//Fetching Members of the Group
var grpMembers = new GlideRecord('sys_user_grmember');
grpMembers.addQuery('group.name', "Demand Managers");
grpMembers.query();
while (grpMembers.next()) {
    users.push(grpMembers.sys_id);
}
//Fetching Members of the Group

for (i = users; i<users.length; i++) {
    //Creation of assessment instance record
    var typeSysID = '489d5c9a47243110020ba9f8536d43b8'; //The sys_id of the assessment, should be in published state
    var sourceRecordID = trigID; //sys_id of the transaction record (Ex: sys_id of the IMS record)
    var userID = users[i]; // sys_id in the opened_by field
    var result = new SNC.AssessmentCreation().createAssessments(typeSysID, sourceRecordID, userID); // successfully created the Survey instance record
    //gs.addInfoMessage('result: '+ result );

    //Association of Trigger ID and Trigger Records
    var asmtGR = new GlideRecord("asmt_assessment_instance");
    asmtGR.get(result.split(",")[0]); // gets the sys_id of the newly created assessment record from the 'result' variable array
    asmtGR.setValue('trigger_table', 'dmn_demand'); //setting target table to demand
    asmtGR.setValue('task_id', trigID); //sys_id of the task id to the current record
    asmtGR.setValue('trigger_id', trigID);
    asmtGR.update();
}
